<template><view class="pet-scene" :class="['scene-'+scene.id,{panorama,reduced,dark}]" :aria-label="panorama?'四象精灵领地':scene.title+'陪伴场景'">
 <template v-if="panorama"><view v-for="p in pets" :key="p.element" class="pet-territory" :class="{'territory-selected':p.element===current.element}" :style="petHouseStyle(p.element,dark,highContrast)"><image class="territory-background" :src="petHouseThemes[p.element].sceneAsset" mode="aspectFill" aria-hidden="true"/><view class="territory-content"><view class="territory-art"><PetHousePetArt :element="p.element" :cosmetic="p.equippedCosmetics[0]"/></view><PetStatusHUD :pet="p" selectable :selected="p.element===current.element" @choose="$emit('choose',$event)"/></view></view></template>
 <template v-else><image v-if="previous" class="scene-background previous-scene" :src="petHouseThemes[previous].sceneAsset" mode="aspectFill" aria-hidden="true"/><image :key="scene.id" class="scene-background current-scene" :src="scene.sceneAsset" mode="aspectFill" aria-hidden="true"/><view class="scene-label"><text>{{scene.title}}</text><text class="small">{{scene.subtitle}}</text></view><view class="scene-character"><PetHousePetArt :element="current.element" :cosmetic="current.equippedCosmetics[0]"/></view><view class="scene-ambient" :class="'ambient-'+scene.motion.type" aria-hidden="true">{{scene.icon}}</view><PetStatusHUD class="scene-hud" :pet="current"/></template>
 </view></template>
<script setup lang="ts">
